MATCH (u:User)-[w:WATCHED]->(m:Movie)
RETURN m.year AS releaseYear, AVG(w.watchCount) AS avgWatchCount, COUNT(DISTINCT u.userId) AS distinctUsers
ORDER BY releaseYear;

MATCH (c:Case {reporterOccupation: 'Consumer'})-[:FALLS_UNDER]->(ag:AgeGroup)
RETURN ag.ageGroup, AVG(c.age) AS averageAge
GROUP BY ag.ageGroup;
